/** How a team gets there: by road if one is open within a turn, else by helicopter, else by BART. */
function howTo(view, from, to) {
  const p = view.path(from, to, { vehicle: 'truck', by: 'safe' })
  if (p.ok && p.hours <= 6) return undefined
  if ((to === 'depot' || (view.districts[to] && view.districts[to].landingZone)) && view.fleet.heli > 0) return 'heli'
  if (view.bartPath(from, to).ok) return 'bart'
  return undefined
}

/** @param {View} view @param {Act} act @param {Record<string, any>} memory */
function onTurn(view, act, memory) {
  const orders = PLAN[view.turn] ?? []
  const used = new Set() // teams already given an order this turn
  const engineer = (at) => view.teams.find((t) => t.kind === 'engineer' && t.at === at && !t.busy && !used.has(t.id))
  for (const o of orders) if (o.kind === 'buy') act.buy(o.item, o.qty)
  for (const o of orders) {
    if (o.kind === 'build') { const e = engineer(o.at); if (act.build(o.at, o.what).ok && e) used.add(e.id) }
    else if (o.kind === 'repair' && view.roads[o.id]) { const e = engineer(view.roads[o.id].district); if (e && act.repair(e.id, o.id).ok) used.add(e.id) }
  }
  for (const o of orders) {
    if (o.kind === 'team') { const t = view.teams.find((x) => x.at === 'depot' && x.kind === o.team && !x.busy && !used.has(x.id)); if (t) { used.add(t.id); act.move(t.id, o.to, howTo(view, 'depot', o.to)) } }
    else if (o.kind === 'move') { const t = view.teams.find((x) => x.id === o.team); used.add(o.team); if (t) act.move(t.id, o.to, howTo(view, t.at, o.to)) }
    else if (o.kind === 'send') {
      const route = o.vehicle === 'truck' || o.vehicle === 'car' ? view.path('depot', o.to, { vehicle: o.vehicle, by: 'safe' }) : undefined
      act.send(o.vehicle, o.to, o.cargo, route && route.ok ? route : undefined)
    }
  }
}
